// Generated by scripts/build-web.mjs. Keeps Cygnus Rx working offline.
const VERSION = 'cygnus-rx-43d77c06175b';
const FILES = ["./",
  "brand-assets/cygnus-swan.png",
  "css/app.css",
  "css/tokens.css",
  "favicon.ico",
  "icons/apple-touch-icon.png",
  "icons/icon-192.png",
  "icons/icon-512.png",
  "icons/maskable-512.png",
  "index.html",
  "js/cert.js",
  "js/druginfo.js",
  "js/drugs.js",
  "js/folder.js",
  "js/layout.js",
  "js/link.js",
  "js/main.js",
  "js/picker.js",
  "js/reference.js",
  "js/render.js",
  "js/safety.js",
  "js/signature.js",
  "js/store.js",
  "js/tests.js",
  "js/ui.js",
  "js/util.js",
  "manifest.webmanifest",
  "vendor/fonts/cinzel-latin-600-normal.woff2",
  "vendor/fonts/ibm-plex-sans-latin-400-normal.woff2",
  "vendor/fonts/ibm-plex-sans-latin-500-normal.woff2",
  "vendor/fonts/ibm-plex-sans-latin-600-normal.woff2",
  "vendor/pdf-lib.mjs",
  "vendor/qrcode.mjs"];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(VERSION).then(c => c.addAll(FILES)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k.startsWith('cygnus-rx-') && k !== VERSION).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

// Files come from the cache first. Calls to Cygnus Rx Link on 127.0.0.1 and
// anything on another address go straight to the network.
self.addEventListener('fetch', e => {
  const url = new URL(e.request.url);
  if (e.request.method !== 'GET' || url.origin !== location.origin) return;
  if (e.request.mode === 'navigate') {
    e.respondWith(caches.match('./', { cacheName: VERSION }).then(r => r || fetch(e.request)));
    return;
  }
  e.respondWith(caches.match(e.request, { ignoreSearch: true }).then(r => r || fetch(e.request)));
});
